def R(y_orig, y_new):
    e_orig = abs(float(y_orig) - 1.0)
    e_new = abs(float(y_new) - 1.0)
    if e_orig < 1e-15:
        return e_new < 1e-15
    ratio = e_new / e_orig
    return ratio <= (0.25 * (2.0 ** 0.2) + 1e-9)
